import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.il0noOp3.js";const m=JSON.parse('{"title":"WAF — enumerated source for the Azure Virtual Desktop workload assessment","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/waf-avd-workload-checklist.md","filePath":"frameworks/waf-avd-workload-checklist.md"}'),i={name:"frameworks/waf-avd-workload-checklist.md"};function s(d,t,n,c,l,h){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="waf-—-enumerated-source-for-the-azure-virtual-desktop-workload-assessment" tabindex="-1">WAF — enumerated source for the Azure Virtual Desktop workload assessment <a class="header-anchor" href="#waf-—-enumerated-source-for-the-azure-virtual-desktop-workload-assessment" aria-label="Permalink to &quot;WAF — enumerated source for the Azure Virtual Desktop workload assessment&quot;">​</a></h1><p><strong>Enumerated 2026-08-01. Verification method and limits are stated below — read them before quoting any coverage number from this page.</strong></p><p>The audit&#39;s DQ12 records why this file exists: <em>&quot;Writing rules against a framework you have not enumerated is how <code>waf.storage.yaml</code> happened&quot;</em> — a rule file scoring a WAF pillar that does not exist. A future <code>waf.avd.yaml</code> is written against this enumeration and nothing else, and every rule in it must cite an item number from the table below.</p><h2 id="what-this-assessment-is" tabindex="-1">What this assessment is <a class="header-anchor" href="#what-this-assessment-is" aria-label="Permalink to &quot;What this assessment is&quot;">​</a></h2><p>Microsoft&#39;s <strong>Azure Well-Architected Framework Azure Virtual Desktop workload assessment</strong> (<a href="https://learn.microsoft.com/en-us/assessments/1ef67c4e-b8d1-4193-b850-d192089ae33d/" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/assessments/1ef67c4e-b8d1-4193-b850-d192089ae33d/</a>) is one of Microsoft&#39;s per-workload specialised reviews (§14, item 5 of <code>pmo/audits/AZURE-SCOUT-AUDIT.md</code>).</p><h2 id="source-—-and-a-scope-correction-made-during-verification" tabindex="-1">Source — and a scope correction made during verification <a class="header-anchor" href="#source-—-and-a-scope-correction-made-during-verification" aria-label="Permalink to &quot;Source — and a scope correction made during verification&quot;">​</a></h2><p>The AI and Azure Local pages both link to a page at <code>azure/well-architected/azure-virtual-desktop/overview</code> as &quot;Virtual Desktop design areas.&quot; <strong>That URL was fetched during this enumeration and resolved to the generic &quot;What is Azure Virtual Desktop?&quot; product-overview page, not a WAF-specific checklist</strong> — the same link-rot pattern the audit&#39;s §8 currency warnings describe for CAF design-area pages. No five-pillar WAF service guide for general Azure Virtual Desktop could be located via Microsoft Learn search or fetch in this pass.</p><p>What <em>is</em> published and retrievable is <strong>&quot;Azure Virtual Desktop for Azure Local&quot;</strong> — an architecture guide scoped specifically to AVD deployed on Azure Local (not AVD in general) that carries a full five-pillar <strong>&quot;Considerations&quot;</strong> section in the same structure as the Azure Local service guide. This is the enumeration below.</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Source page</td><td><a href="https://learn.microsoft.com/en-us/azure/architecture/hybrid/azure-local-workload-virtual-desktop" target="_blank" rel="noreferrer">Azure Virtual Desktop for Azure Local</a> — <strong>Considerations</strong> section</td></tr><tr><td>Scope</td><td><strong>AVD on Azure Local only.</strong> This is narrower than the general Azure Virtual Desktop workload assessment, which covers AVD on native Azure infrastructure too.</td></tr><tr><td>Framework version</td><td>Azure Well-Architected Framework, current — five pillars: Reliability, Security, Cost Optimization, Operational Excellence, Performance Efficiency</td></tr><tr><td>Extraction date</td><td>2026-08-01</td></tr><tr><td>Verification method</td><td>Full page fetched via the Microsoft Learn MCP <code>microsoft_docs_fetch</code> tool and read start to end. Every bullet under each pillar&#39;s heading in the <strong>Considerations</strong> section is transcribed below.</td></tr></tbody></table><h2 id="the-gap-this-leaves" tabindex="-1">The gap this leaves <a class="header-anchor" href="#the-gap-this-leaves" aria-label="Permalink to &quot;The gap this leaves&quot;">​</a></h2><p><strong>General (non-Azure-Local) Azure Virtual Desktop does not have an enumerated WAF checklist in this file.</strong> The interactive assessment tool&#39;s question text isn&#39;t published, exactly as with SMART and the other three checklists in this release. A rule file built only from the enumeration below will score AVD-on-Azure-Local-shaped concerns (FSLogix-on-S2D, Azure Local cluster health) accurately, but will under-represent concerns specific to AVD on native Azure (host pool autoscale on Azure compute, Azure Files/NetApp Files for FSLogix, Azure-region-based landing zone design). This is a documented gap, not a fabricated item — closing it is a follow-up task, not a guess made here.</p><p><strong>Shelf life.</strong> Re-verify before quoting, and re-date this page when you do.</p><h2 id="the-enumeration-—-20-items-across-5-pillars-avd-on-azure-local" tabindex="-1">The enumeration — 20 items across 5 pillars (AVD on Azure Local) <a class="header-anchor" href="#the-enumeration-—-20-items-across-5-pillars-avd-on-azure-local" aria-label="Permalink to &quot;The enumeration — 20 items across 5 pillars (AVD on Azure Local)&quot;">​</a></h2><h3 id="reliability-waf-avd-re-—-4-items" tabindex="-1">Reliability (WAF-AVD-RE) — 4 items <a class="header-anchor" href="#reliability-waf-avd-re-—-4-items" aria-label="Permalink to &quot;Reliability (WAF-AVD-RE) — 4 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout collector</th></tr></thead><tbody><tr><td>WAF-AVD-RE-01</td><td>Implement multiple-machine instances for high availability</td><td>✅ <code>Hybrid/Clusters</code> (node count)</td></tr><tr><td>WAF-AVD-RE-02</td><td>Plan and regularly test backup and restore procedures for VMs and user profiles</td><td>✅ <code>Management/RecoveryVault</code>, <code>Management/BackupInstances</code> — presence readable; test cadence is not</td></tr><tr><td>WAF-AVD-RE-03</td><td>Implement monitoring and alerting for Azure Local and AVD VMs</td><td>✅ <code>Monitor/MetricAlertRules</code>, <code>Monitor/ActionGroups</code>, <code>Compute/AVDSessionHosts</code> (health state field)</td></tr><tr><td>WAF-AVD-RE-04</td><td>Test failover and disaster recovery regularly</td><td>❌ Unanswerable — a test-execution cadence, not an ARM property</td></tr></tbody></table><h3 id="security-waf-avd-se-—-4-items" tabindex="-1">Security (WAF-AVD-SE) — 4 items <a class="header-anchor" href="#security-waf-avd-se-—-4-items" aria-label="Permalink to &quot;Security (WAF-AVD-SE) — 4 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout collector</th></tr></thead><tbody><tr><td>WAF-AVD-SE-01</td><td>Turn on Microsoft Entra multifactor authentication for AVD access</td><td>⚠️ Partial — <code>Identity/ConditionalAccess</code> can show an MFA-requiring policy exists; per-user enforcement isn&#39;t collected</td></tr><tr><td>WAF-AVD-SE-02</td><td>Update and patch AVD session hosts regularly (Azure Update Manager)</td><td>✅ <code>Management/PolicyComplianceStates</code> (Update Manager compliance path)</td></tr><tr><td>WAF-AVD-SE-03</td><td>Protect against threats and vulnerabilities (Defender for Cloud)</td><td>✅ <code>Security/DefenderPricing</code>, <code>Security/DefenderAlerts</code></td></tr><tr><td>WAF-AVD-SE-04</td><td>Isolate networks (separate logical networks/VLANs for the workload)</td><td>✅ <code>Hybrid/LogicalNetworks</code></td></tr></tbody></table><h3 id="cost-optimization-waf-avd-co-—-6-items" tabindex="-1">Cost Optimization (WAF-AVD-CO) — 6 items <a class="header-anchor" href="#cost-optimization-waf-avd-co-—-6-items" aria-label="Permalink to &quot;Cost Optimization (WAF-AVD-CO) — 6 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout collector</th></tr></thead><tbody><tr><td>WAF-AVD-CO-01</td><td>Optimize VM sizing for cost efficiency (rightsize against usage)</td><td>⚠️ Partial — <code>Compute/AVDSessionHosts</code> reports SKU; usage-pattern correlation is a rule-authoring task, not a missing collector</td></tr><tr><td>WAF-AVD-CO-02</td><td>Use automatic VM guest OS patching for Azure Local VMs</td><td>✅ Same signal as WAF-AVD-SE-02</td></tr><tr><td>WAF-AVD-CO-03</td><td>Choose single-session or multi-session host pools deliberately</td><td>✅ <code>Compute/AVD</code> (host pool type property)</td></tr><tr><td>WAF-AVD-CO-04</td><td>Consolidate cost monitoring (Insights, Update Manager)</td><td>⚠️ Partial — <code>Monitor/Workspaces</code> evidences Insights is configured; cost-consolidation practice itself isn&#39;t scorable</td></tr><tr><td>WAF-AVD-CO-05</td><td>Plan for initial workload capacity and growth (2/3-node switchless where it fits)</td><td>❌ Unanswerable — a pre-deployment capacity-planning decision</td></tr><tr><td>WAF-AVD-CO-06</td><td>Implement Azure Virtual Desktop autoscaling</td><td>✅ <code>Compute/AVDScalingPlans</code></td></tr></tbody></table><h3 id="operational-excellence-waf-avd-oe-—-4-items" tabindex="-1">Operational Excellence (WAF-AVD-OE) — 4 items <a class="header-anchor" href="#operational-excellence-waf-avd-oe-—-4-items" aria-label="Permalink to &quot;Operational Excellence (WAF-AVD-OE) — 4 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout collector</th></tr></thead><tbody><tr><td>WAF-AVD-OE-01</td><td>Use simplified provisioning and management (ARM templates for deployment)</td><td>❌ Unanswerable — a deployment-process choice, not a post-deployment property</td></tr><tr><td>WAF-AVD-OE-02</td><td>Create strict change-control procedures (test/validate before production)</td><td>❌ Organisational</td></tr><tr><td>WAF-AVD-OE-03</td><td>Use automation capabilities for VMs (Arc extensions, Update Manager, Azure Automation)</td><td>✅ <code>Hybrid/ArcExtensions</code></td></tr><tr><td>WAF-AVD-OE-04</td><td>Set up monitoring and logging (Insights for Azure Local and AVD)</td><td>✅ <code>Monitor/Workspaces</code>, <code>Compute/AVD</code> (Insights-linked workspace reference)</td></tr></tbody></table><h3 id="performance-efficiency-waf-avd-pe-—-2-items" tabindex="-1">Performance Efficiency (WAF-AVD-PE) — 2 items <a class="header-anchor" href="#performance-efficiency-waf-avd-pe-—-2-items" aria-label="Permalink to &quot;Performance Efficiency (WAF-AVD-PE) — 2 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout collector</th></tr></thead><tbody><tr><td>WAF-AVD-PE-01</td><td>Use load balancing for optimal performance (breadth-first / depth-first)</td><td>✅ <code>Compute/AVD</code> (load-balancer-type property on the host pool)</td></tr><tr><td>WAF-AVD-PE-02</td><td>Optimize performance — high-performance storage, S2D pooling, performance testing</td><td>⚠️ Partial — <code>Hybrid/Clusters</code> may expose storage tier data depending on API version; performance-test execution is not collected</td></tr></tbody></table><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pillar</th><th>Items</th><th>Answerable (✅)</th><th>Partial (⚠️)</th><th>Unanswerable (❌)</th></tr></thead><tbody><tr><td>Reliability</td><td>4</td><td>3</td><td>0</td><td>1</td></tr><tr><td>Security</td><td>4</td><td>3</td><td>1</td><td>0</td></tr><tr><td>Cost Optimization</td><td>6</td><td>3</td><td>2</td><td>1</td></tr><tr><td>Operational Excellence</td><td>4</td><td>2</td><td>0</td><td>2</td></tr><tr><td>Performance Efficiency</td><td>2</td><td>1</td><td>1</td><td>0</td></tr><tr><td><strong>Total</strong></td><td><strong>20</strong></td><td><strong>12</strong></td><td><strong>4</strong></td><td><strong>4</strong></td></tr></tbody></table><p>12 of 20 items (60%) map cleanly to an existing collector — the highest automatable fraction of the four checklists in this release, because AVD-on-Azure-Local is infrastructure-heavy and Scout already collects both the AVD (<code>Compute/AVD*</code>) and Azure Local (<code>Hybrid/*</code>) collector families it depends on.</p><h2 id="what-this-means-for-the-rule-file" tabindex="-1">What this means for the rule file <a class="header-anchor" href="#what-this-means-for-the-rule-file" aria-label="Permalink to &quot;What this means for the rule file&quot;">​</a></h2><p>A future <code>waf.avd.yaml</code> should cite <code>WAF-AVD-*</code> item numbers. Because this enumeration is scoped to AVD-on-Azure-Local, the rule file inherits that scope; a rule that only makes sense for AVD on native Azure compute (for example, autoscale cost tiers specific to Azure VM pricing) should not be written against this file without a corresponding enumeration of the general AVD workload assessment first.</p>',28)])])}const p=e(i,[["render",s]]);export{m as __pageData,p as default};
